#!/usr/bin/env node
/**
 * Zperiod — UI dictionary generator for the Central-/Northern-European slice.
 *
 * Locales owned by this file: nl, sv, no, da, fi, cs, sk, hu, ro, bg, hr, sr, lt
 * (all other locales in src/i18n/languages.ts are owned by other workers.)
 *
 * This script is the maintainable SOURCE OF TRUTH: the JSON files under
 * src/i18n/translations/ are generated artefacts. Run:
 *
 *     node scripts/build-latin-european-dicts.mjs          # write the 13 files
 *     node scripts/build-latin-european-dicts.mjs --check  # validate only
 *
 * Shape: one entry per UI_KEY, every value a 13-slot object keyed by locale.
 * Keeping all locales side by side on one line makes placeholder drift
 * (`{n}`, `{el}`, `{z}`, `{sym}`) and accidental English leftovers obvious.
 *
 * The English reference (src/i18n/translations/en.json) defines what each key
 * MEANS and which keys are substitution templates, so --check also asserts
 * placeholder parity against it. Pass `--no-en` to skip that assertion.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..');
const KEYS_FILE = path.join(ROOT, 'src/i18n/keys.ts');
const OUT_DIR = path.join(ROOT, 'src/i18n/translations');
const EN_FILE = path.join(OUT_DIR, 'en.json');

/** The 13 locales this worker owns — order is fixed and used everywhere. */
const LOCALES = ['nl', 'sv', 'no', 'da', 'fi', 'cs', 'sk', 'hu', 'ro', 'bg', 'hr', 'sr', 'lt'];

/** Key contract, parsed straight out of keys.ts (never retyped). */
function readContract() {
  const src = fs.readFileSync(KEYS_FILE, 'utf8');
  return [...src.matchAll(/^ {2}'([a-zA-Z0-9._-]+)',$/gm)].map((m) => m[1]);
}

