D['landing.feature.atoms.body'] = { nl: 'Draai elk atoom, wissel tussen schillen- en wolkmodellen en zie precies waar de elektronen zitten.', sv: 'Rotera valfritt atom, växla mellan skal- och molnmodeller och se exakt var elektronerna sitter.', no: 'Roter hvert atom, bytt mellom skall- og skymodeller, og se nøyaktig hvor elektronene sitter.', da: 'Roter hvert atom, skift mellem skal- og skymodeller, og se præcis, hvor elektronerne sidder.', fi: 'Pyöritä mitä tahansa atomia, vaihda kuori- ja pilvimallien välillä ja katso tarkalleen, missä elektronit ovat.', cs: 'Otočte libovolný atom, přepínejte mezi modelem slupek a oblakem a uvidíte přesně, kde jsou jeho elektrony.', sk: 'Otočte ľubovoľný atóm, prepínajte medzi modelom vrstiev a oblakom a uvidíte presne, kde sú jeho elektróny.', hu: 'Forgasd bármelyik atomot, válts a héj- és felhőmodellek között, és lásd pontosan, hol vannak az elektronok.', ro: 'Rotește orice atom, comută între modelele de învelișuri și nori, și vezi exact unde stau electronii.', bg: 'Завъртайте всеки атом, превключвайте между модела на слоеве и облаци и виждайте точно къде са електроните.', hr: 'Okrećite bilo koji atom, prelazite između modela ljusaka i oblaka i točno vidite gdje su njegovi elektroni.', sr: 'Okrećite bilo koji atom, prelazite između modela ljusaka i oblaka i tačno vidite gde su njegovi elektroni.', lt: 'Sukite bet kurį atomą, perjunkite tarp sluoksnių ir debesų modelių ir tiksliai pamatysite, kur yra jo elektronai.' };
D['landing.feature.tools.title'] = { nl: 'Scheikundetools', sv: 'Kemiverktyg', no: 'Kjemiverktøy', da: 'Kemiværktøj', fi: 'Kemian työkalut', cs: 'Chemické nástroje', sk: 'Chemické nástroje', hu: 'Kémiai eszközök', ro: 'Unelte de chimie', bg: 'Химични инструменти', hr: 'Kemijski alati', sr: 'Hemijski alati', lt: 'Chemijos įrankiai' };
D['landing.feature.tools.body'] = { nl: 'Klok reacties uit, bereken molaire massa, controleer de oplosbaarheid en voer een virtueel oplosbaarheidsexperiment uit.', sv: 'Balansera reaktioner, beräkna molmassa, kontrollera löslighet och kör ett virtuellt löslighetslabb.', no: 'Balanser reaksjoner, beregn molmasse, sjekk løselighet og kjør et virtuelt løselighetslaboratorium.', da: 'Balancér reaktioner, beregn molmasse, tjek opløselighed, og kør et virtuelt opløselighedslaboratorium.', fi: 'Tasapainota reaktioita, laske molaarimassoja, tarkista liukoisuutta ja aja virtuaalista liukoisuuslaboratoriaa.', cs: 'Vyčíslete rovnice, spočítejte molární hmotnosti, ověřte rozpustnost a pusťte si virtuální laboratoř rozpustnosti.', sk: 'Vyčíslite rovnice, vypočítajte molárne hmotnosti, overte rozpustnosť a spustite virtuálnu laboratóriu rozpustnosti.', hu: 'Rendezz egyenleteket, számíts moláris tömegeket, ellenőrizd az oldhatóságot, és futtass virtuális oldhatósági laboratóriumot.', ro: 'Echilibrează ecuații, calculează mase molare, verifică solubilitatea și rulează un laborator virtual de solubilitate.', bg: 'Изравнете уравнения, изчислете моларни маси, проверете разтворимостта и стартирайте виртуална лаборатория за разтворимост.', hr: 'Uravnotežite jednadžbe, izračunajte molarne mase, provjerite topljivost i pokrenite virtualni laboratorij topljivosti.', sr: 'Uravnotežite jednačine, izračunajte molarne mase, proverite rastvorljivost i pokrenite virtuelni laboratorij rastvorljivosti.', lt: 'Išlyginkite lygtis, apskaičiuokite molines masses, patikrinkite tirpumą ir paleiskite virtualų tirpumo laboratoriją.' };
D['landing.feature.ions.title'] = { nl: 'Ionverkenner', sv: 'Joner', no: 'Ionutforsker', da: 'Ionudforsker', fi: 'Ionitutkija', cs: 'Průzkumník iontů', sk: 'Prieskumník iónov', hu: 'Ionkutató', ro: 'Explorator de ioni', bg: 'Разгледач на йони', hr: 'Pretraživač iona', sr: 'Pretraživač jona', lt: 'Jonų tyrinėtojas' };
D['landing.feature.ions.body'] = { nl: 'Doorzoek eenatomige en meeratomige ionen met lading, massa en elektronenconfiguratie.', sv: 'Utforska enatomiga och fleratomiga joner med laddning, massa och elektronkonfiguration.', no: 'Utforsk monoatomiske og fleratomige ioner med ladning, masse og elektronkonfigurasjon.', da: 'Udforsk monoatomiske og fleratomige ioner med ladning, masse og elektronkonfiguration.', fi: 'Selaa yksiatomisia ja moniosakkoisia ioneita niiden latauksen, massan ja elektronikonfiguraation avulla.', cs: 'Prohlížejte jednoatomové a polyatomické ionty s nábojem, hmotností a elektronovou konfigurací.', sk: 'Prehliadajte jednoatómové a polyatómové ióny s nábojom, hmotnosťou a elektrónovou konfiguráciou.', hu: 'Böngéssz az egyatomos és többatomos ionok között töltés, tömeg és elektronkonfiguráció alapján.', ro: 'Explorează ionii monoatomici și poliatomici cu sarcina, masa și configurația electronică.', bg: 'Разгледайте едноатомните и многоатомните йони със заряд, маса и електронна конфигурация.', hr: 'Pretražite monoatomske i poliatomske ione s nabojem, masom i elektronskom konfiguracijom.', sr: 'Pretražite monoatomske i poliatomske jone sa naelektronom, masom i elektronskom konfiguracijom.', lt: 'Naršykite monoatominius ir poliatominius jonus pagal kryptį, masę ir elektronų konfigūraciją.' };
D['landing.feature.worksheet.title'] = { nl: 'Werkbladgenerator', sv: 'Arbetsbladsgenerator', no: 'Arbeidsarkgenerator', da: 'Arbejdsarksgenerator', fi: 'Työkirjojen luonti', cs: 'Generátor pracovních listů', sk: 'Generátor pracovných listov', hu: 'Munkalap-generátor', ro: 'Generator de fișe de lucru', bg: 'Генератор на работни листи', hr: 'Generator radnih listova', sr: 'Generator radnih listova', lt: 'Darbo lapų kūrimas' };
D['landing.feature.worksheet.body'] = { nl: 'Stel werkbladen met reactievergelijkingen samen per type en moeilijkheid, inclusief volledige antwoordsleutel, met één klik.', sv: 'Skapa arbetsblad med reaktionsformler per typ och svårighetsgrad, med komplett facit, med ett klick.', no: 'Lag arbeidsark med reaksjonsligninger etter type og vanskelighetsgrad, med fullstendig fasit, med ett klikk.', da: 'Sammensæt arbejdsark med reaktionsformler efter type og sværhedsgrad, med komplet facit, med ét klik.', fi: 'Kokoa reaktioyhtälöitä sisältäviä työkirjoja tyypin ja vaikeustason mukaan, täydellisen vastauksine mukaan, yhdellä napsautuksella.', cs: 'Sestavte pracovní listy s rovnicemi podle typu a obtížnosti, včetně kompletního klíče, jedním kliknutím.', sk: 'Zostavte pracovné listy s rovnicami podľa typu a obťažnosti, vrátane kompletného kľúča, jedným kliknutím.', hu: 'Állíts össze reakcióegyenletes munkalapokat típus és nehézség szerint, teljes megoldókulccsal, egyetlen kattintással.', ro: 'Construiește fișe cu ecuații de reacție după tip și dificultate, cu un barem complet, într-un singur clic.', bg: 'Създавайте работни листи с уравнения по вид и трудност, с пълен отговор, с един клик.', hr: 'Sastavite radne listove s jednadžbama prema vrsti i težini, s potpunim ključem, jednim klikom.', sr: 'Sastavite radne listove sa jednačinama prema vrsti i težini, sa potpunim ključem, jednim klikom.', lt: 'Sukurkite reakcijų lygtis užduočių lapus pagal tipą ir sunkumą, su visa atsakymų raktu, vienu paspaudimu.' };
D['landing.feature.learn.title'] = { nl: 'Leerpad', sv: 'Lärandeväg', no: 'Læringsvei', da: 'Læringsvej', fi: 'Oppimispolku', cs: 'Učební cesta', sk: 'Učebná cesta', hu: 'Tanulási út', ro: 'Traseu de învățare', bg: 'Учебен път', hr: 'Učni put', sr: 'Učni put', lt: 'Mokymosi kelias' };
D['landing.feature.learn.body'] = { nl: 'Werk je door korte lessen en kaarten die onthouden wat je al beheerst.', sv: 'Gå igenom korta lektioner och kort som håller reda på vad du redan behärskar.', no: 'Jobb deg gjennom korte leksjoner og kort som holder styr på hva du allerede har mestret.', da: 'Arbejd dig gennem korte lektioner og kort, der holder styr på, hvad du allerede har mestret.', fi: 'Käy läpi lyhyet oppitunnit ja kortit, jotka muistavat jo osaamasi.', cs: 'Projděte si krátké lekce a karty, které si pamatují, co už zvládnete.', sk: 'Prejdite si krátke lekcie a karty, ktoré si pamätajú, čo už zvládnete.', hu: 'Végig haladj rövid lekéken és kártyákon, amelyek emlékeznek arra, mit már megtanultál.', ro: 'Parcurge lecții scurte și fișe care rețin ce ai deja stăpânit.', bg: 'Преминете през кратки уроци и карти, които помнят какво вече сте усвоили.', hr: 'Prođite kroz kratke lekcije i kartice koje pamte što ste već svladali.', sr: 'Prođite kroz kratke lekcije i kartice koje pamte šta ste već svladali.', lt: 'Peržiūrėkite trumpas pamokas ir korteles, kurios prisimena, ką jau įvaldote.' };
D['landing.privacy'] = { nl: 'Geen accounts, geen tracking — alles draait in je browser.', sv: 'Inga konton, ingen spårning — allt körs i webbläsaren.', no: 'Ingen kontoer, ingen sporing — alt kjører i nettleseren.', da: 'Ingen konti, ingen sporing — alt kører i browseren.', fi: 'Ei käyttäjätilejä eikä seurantaa — kaikki toimii selaimessa.', cs: 'Žádné účty, žádné sledování — vše běží ve vašem prohlížeči.', sk: 'Žiadne účty, žiadne sledovanie — všetko beží vo vašom prehliadači.', hu: 'Nincsenek fiókok és követés — minden a böngésződben fut.', ro: 'Fără conturi, fără urmărire — totul rulează în browserul tău.', bg: 'Без акаунти и без проследяване — всичко работи в браузъра ви.', hr: 'Bez računa, bez praćenja — sve radi u vašem pregledniku.', sr: 'Bez naloga, bez praćenja — sve radi u vašem pregledaču.', lt: 'Nepaskų, be sekimo — viskas veikia jūsų naršyklėje.' };

