// ── emit / validate ────────────────────────────────────────────────────────
const placeholders = (s) => (s.match(/\{[a-z]+\}/g) || []).sort().join(',');

function readEnglish() {
  if (process.argv.includes('--no-en')) return null;
  if (!fs.existsSync(EN_FILE)) {
    console.warn(`note: ${path.relative(ROOT, EN_FILE)} not found — skipping English parity check`);
    return null;
  }
  return JSON.parse(fs.readFileSync(EN_FILE, 'utf8'));
}

function build() {
  const contract = readContract();
  const en = readEnglish();
  const errors = [];

  for (const key of contract) {
    if (!D[key]) {
      errors.push(`MISSING ENTRY: ${key}`);
      continue;
    }
    for (const loc of LOCALES) {
      const v = D[key][loc];
      if (typeof v !== 'string' || !v.trim()) errors.push(`${loc} empty: ${key}`);
      else if (/<[a-z/][^>]*>/i.test(v)) errors.push(`${loc} HTML in value: ${key}`);
    }
  }
  for (const key of Object.keys(D)) {
    if (!contract.includes(key)) errors.push(`EXTRA ENTRY (not in contract): ${key}`);
    else for (const loc of LOCALES) if (!(loc in D[key])) errors.push(`${loc} missing value: ${key}`);
  }
  // Placeholder parity across the 13 locales …
  for (const key of contract) {
    if (!D[key]) continue;
    const set = new Set(LOCALES.map((l) => placeholders(D[key][l])));
    if (set.size > 1) errors.push(`placeholder drift between locales on ${key}: ${[...set].join(' | ')}`);
  }
  // … and against the English reference, which owns the substitution contract.
  if (en) {
    for (const key of contract) {
      if (!D[key] || !(key in en)) continue;
      for (const loc of LOCALES) {
        if (placeholders(D[key][loc]) !== placeholders(en[key])) {
          errors.push(`placeholder drift vs en on ${key} (${loc}): en "${en[key]}" vs "${D[key][loc]}"`);
        }
      }
    }
  }

  if (errors.length) {
    console.error('DICTIONARY ERRORS:\n' + errors.join('\n'));
    process.exit(1);
  }

  fs.mkdirSync(OUT_DIR, { recursive: true });
  for (const loc of LOCALES) {
    const out = {};
    for (const key of contract) out[key] = D[key][loc];
    const file = path.join(OUT_DIR, `${loc}.json`);
    const json = JSON.stringify(out, null, 2) + '\n';
    if (process.argv.includes('--check')) {
      if (!fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== json) {
        console.error(`STALE: ${file} differs from generator output`);
        process.exit(1);
      }
      console.log(`ok  ${loc}  ${contract.length} keys`);
    } else {
      fs.writeFileSync(file, json);
      console.log(`wrote ${loc}  ${contract.length} keys  ->  ${path.relative(ROOT, file)}`);
    }
  }
}

build();
